import React, { useState, useEffect } from 'react';
import { Flow } from 'flow-sdk';
import { Sidebar } from './components/Sidebar';
import { DropZone } from './components/DropZone';
import { Preview } from './components/Preview';
import { MediaItem } from './types';

export default function App() {
  const [sourceMedia, setSourceMedia] = useState<MediaItem | null>(null);
  const [resultMedia, setResultMedia] = useState<MediaItem | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Settings
  const [model, setModel] = useState('Omni Flash');
  const [style, setStyle] = useState('Classic RPG');
  const [aspectRatio, setAspectRatio] = useState<'16:9' | '9:16'>('16:9');

  useEffect(() => {
    const id = 'flow-design-system-css';
    if (document.getElementById(id)) return;
    const styleTag = document.createElement('style');
    styleTag.id = id;
    styleTag.textContent = `
      @keyframes shimmer {
        0% { background-position: -1000px 0; }
        100% { background-position: 1000px 0; }
      }
      .animate-shimmer {
        background: linear-gradient(to right, #1a1a1a 8%, #2a2a2a 18%, #1a1a1a 33%);
        background-size: 1000px 100%;
        animation: shimmer 2s infinite linear;
      }
      input[type=range] { -webkit-appearance: none; appearance: none; background: transparent; width: 100%; cursor: pointer; padding: 8px 0; }
      input[type=range]::-webkit-slider-runnable-track { width: 100%; height: 3px; background: #595959; border-radius: 9999px; }
      input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; appearance: none; width: 14px; height: 14px; border-radius: 50%; background: white; box-shadow: 0px 1px 3px rgba(0,0,0,0.5); margin-top: -5.5px; cursor: grab; }
      .dark-scrollbar { scrollbar-width: thin; scrollbar-color: #595959 transparent; }
      .dark-scrollbar::-webkit-scrollbar { width: 6px; }
      .dark-scrollbar::-webkit-scrollbar-track { background: transparent; }
      .dark-scrollbar::-webkit-scrollbar-thumb { background: #595959; border-radius: 9999px; }
      @keyframes dropdown-enter { from { opacity: 0; transform: scale(0.95) translateY(-5px); } to { opacity: 1; transform: scale(1) translateY(0); } }
      .animate-dropdown { animation: dropdown-enter 0.15s ease-out forwards; }
      html, body, #root { margin: 0; padding: 0; width: 100%; height: 100%; background: #0e0e0e; font-family: 'Google Sans Text', 'Google Sans', sans-serif; letter-spacing: 0.1px; }
    `;
    document.head.appendChild(styleTag);
  }, []);

  const handleSelect = async () => {
    try {
      const media = await Flow.media.select({ filter: 'video' });
      if (media) {
        setSourceMedia(media);
        setResultMedia(null);
        setError(null);
      }
    } catch (err) {
      console.error(err);
    }
  };

  const handleGenerate = async () => {
    if (!sourceMedia) return;

    setIsGenerating(true);
    setError(null);

    try {
      // Construct prompt based on style
      const prompts: Record<string, string> = {
        'Classic RPG': '8-bit adventure game style, pixel art, retro aesthetics, vibrant retro colors, high quality pixelation, NES style.',
        'Chibi Adventure': '8-bit cute adventure game, chibi style characters with big heads and small bodies, vibrant kawaii pixel art, retro handheld aesthetic, high quality 8-bit sprites, adorable pixel animation.',
        'SNES Adventure': '16-bit adventure game style, high quality pixel art, vibrant color palette, SNES aesthetic, detailed retro backgrounds, cinematic pixel animation, smooth retro motion.',
        'Game Boy Retro': 'Classic Game Boy handheld style, 4-shade monochrome green palette, retro dot matrix display effect, chunky 8-bit pixels, nostalgic portable game aesthetic, greenish tint.',
        'Cyberpunk Quest': '8-bit cyberpunk adventure game, neon pixel art, retro-futuristic, high contrast, dark synthwave palette.',
        'Dark Dungeon': '8-bit dark fantasy dungeon crawler, gritty pixel art, gothic retro style, limited palette, atmospheric lighting.',
        'Retro Forest': '8-bit handheld game style, lush green pixel art, forest environment, bright and colorful, Gameboy Advance aesthetic.',
        'Arcade Brawler': '8-bit beat em up style, chunky pixel art, high contrast colors, gritty urban environment, retro arcade cabinet aesthetic.'
      };

      const result = await Flow.generate.video({
        prompt: prompts[style] || prompts['Classic RPG'],
        sourceVideoMediaId: sourceMedia.mediaId,
        sourceVideoMode: 'edit',
        modelDisplayName: model,
        aspectRatio: aspectRatio,
      });

      setResultMedia({
        mediaId: result.mediaId,
        base64: result.base64,
        mimeType: result.mimeType,
        type: 'video',
        name: 'Retro Quest Result'
      });
    } catch (err: any) {
      setError(err?.message || 'Failed to generate video. Please try again.');
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="flex h-screen w-screen bg-[#0e0e0e] text-white overflow-hidden">
      {/* Sidebar - Flush to left edge */}
      <Sidebar 
        model={model} setModel={setModel}
        style={style} setStyle={setStyle}
        aspectRatio={aspectRatio} setAspectRatio={setAspectRatio}
        onGenerate={handleGenerate}
        isGenerating={isGenerating}
        hasSource={!!sourceMedia}
      />

      {/* Main Content Area */}
      <main className="flex-1 relative flex flex-col items-center justify-center p-8 overflow-y-auto dark-scrollbar">
        {error && (
          <div className="absolute top-8 left-1/2 -translate-x-1/2 z-20 bg-red-500/10 border border-red-500/20 px-4 py-2 rounded-xl text-red-400 text-xs flex items-center gap-2">
            <span className="material-symbols-outlined text-[18px]">error</span>
            {error}
          </div>
        )}

        {!sourceMedia ? (
          <DropZone onSelect={handleSelect} />
        ) : (
          <Preview 
            source={sourceMedia} 
            result={resultMedia} 
            isGenerating={isGenerating}
            onReset={() => { setSourceMedia(null); setResultMedia(null); }}
          />
        )}
      </main>
    </div>
  );
}

export interface MediaItem {
  mediaId: string;
  base64: string;
  mimeType: string;
  type: 'image' | 'video' | 'audio';
  name: string;
}

import React, { useState, useRef, useEffect } from 'react';
import { PillButton, SectionLabel, FieldDropdown, SegmentedToggle } from './Primitives';

interface SidebarProps {
  model: string;
  setModel: (v: string) => void;
  style: string;
  setStyle: (v: string) => void;
  aspectRatio: '16:9' | '9:16';
  setAspectRatio: (v: '16:9' | '9:16') => void;
  onGenerate: () => void;
  isGenerating: boolean;
  hasSource: boolean;
}

export const Sidebar: React.FC<SidebarProps> = ({
  model, setModel,
  style, setStyle,
  aspectRatio, setAspectRatio,
  onGenerate, isGenerating,
  hasSource
}) => {
  return (
    <div className="relative border-r border-[rgba(218,220,224,0.15)] flex flex-col items-start justify-between px-[10px] py-[12px] w-[300px] h-full min-h-0 bg-[#0e0e0e]">
      <div className="flex flex-col gap-[24px] items-start w-full">

        {/* Style Selection */}
        <div className="flex flex-col gap-2 items-start w-full">
          <SectionLabel>Visual Style</SectionLabel>
          <div className="flex flex-col gap-1.5 w-full">
            <FieldDropdown 
              label="Preset" 
              value={style}
              options={[
                'Classic RPG', 
                'SNES Adventure',
                'Game Boy Retro',
                'Chibi Adventure', 
                'Cyberpunk Quest', 
                'Dark Dungeon', 
                'Retro Forest', 
                'Arcade Brawler'
              ]}
              onChange={setStyle}
            />
          </div>
        </div>

        {/* Output Settings */}
        <div className="flex flex-col gap-2 items-start w-full">
          <SectionLabel>Generation Settings</SectionLabel>
          <div className="flex flex-col gap-1.5 w-full">
            <FieldDropdown 
              label="AI Model" 
              value={model}
              options={['Omni Flash']}
              onChange={setModel}
            />
            <div className="mt-2">
              <SectionLabel>Aspect Ratio</SectionLabel>
              <div className="mt-1">
                <SegmentedToggle 
                  value={aspectRatio}
                  onChange={(v) => setAspectRatio(v as any)}
                  items={[
                    { value: '16:9', label: '16:9' },
                    { value: '9:16', label: '9:16' }
                  ]}
                />
              </div>
            </div>
          </div>
        </div>

        <div className="flex flex-col gap-2 w-full mt-4 p-3 bg-white/5 rounded-xl border border-white/10">
          <p className="text-[10px] text-white/50 leading-relaxed">
            <span className="text-white/80 font-medium block mb-1 uppercase tracking-wider">How it works</span>
            Upload a video clip (max 10s). The Omni Flash model will process each frame into a stylistically consistent retro cinematic based on your preset.
          </p>
        </div>

      </div>

      {/* Bottom Action */}
      <div className="flex flex-col gap-[5px] items-start w-full pt-2">
        <PillButton 
          variant="solid" 
          onClick={onGenerate}
          disabled={isGenerating || !hasSource}
          icon={<span className="material-symbols-outlined text-[18px]">{isGenerating ? 'progress_activity' : 'bolt'}</span>}
        >
          {isGenerating ? 'Processing...' : 'Generate Quest'}
        </PillButton>
      </div>
    </div>
  );
};

import React from 'react';

interface DropZoneProps {
  onSelect: () => void;
}

export const DropZone: React.FC<DropZoneProps> = ({ onSelect }) => {
  return (
    <button 
      onClick={onSelect}
      className="group relative w-full max-w-2xl aspect-video rounded-3xl border-2 border-dashed border-white/10 hover:border-white/30 bg-white/[0.02] hover:bg-white/[0.04] transition-all flex flex-col items-center justify-center gap-6 cursor-pointer overflow-hidden"
    >
      <div className="relative">
        <div className="absolute inset-0 bg-white/10 blur-3xl rounded-full scale-150 group-hover:scale-175 transition-transform opacity-0 group-hover:opacity-100" />
        <div className="w-20 h-20 rounded-2xl bg-white/5 border border-white/10 flex items-center justify-center group-hover:scale-110 group-hover:rotate-3 transition-transform">
          <span className="material-symbols-outlined text-[40px] text-white/40 group-hover:text-white/80">video_library</span>
        </div>
      </div>

      <div className="text-center">
        <h2 className="text-xl font-medium text-white group-hover:translate-y-[-2px] transition-transform">Begin your Quest</h2>
        <p className="text-sm text-white/40 mt-1">Upload a video to convert it to 8-bit adventure style</p>
      </div>

      <div className="flex gap-4 mt-2">
        {['RPG', 'CYBER', 'DARK'].map(label => (
          <span key={label} className="px-3 py-1 rounded-full bg-white/5 border border-white/10 text-[10px] font-bold tracking-widest text-white/30 uppercase group-hover:text-white/60 transition-colors">
            {label}
          </span>
        ))}
      </div>
    </button>
